from collections import defaultdict

def create_graph(cfg):
    n = len(cfg)
    graph = {i: [] for i in range(n)}
    for i in range(n):
        for j in range(n):
            if cfg[i][j] == 'A':
                graph[i].append(j)
            elif cfg[i][j] == 'O':
                graph[j].append(i)
    return graph

def bfs(graph, start):
    visited = [False] * len(graph)
    queue = [start]
    visited[start] = True
    level = 0
    parent = [-1] * len(graph)

    while queue:
        level += 1
        next_level = []
        for node in queue:
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    next_level.append(neighbor)
                    visited[neighbor] = True
                    parent[neighbor] = node
        queue = next_level
    return level, parent

def compute_min_paths(graph):
    n = len(graph)
    min_paths = defaultdict(int)
    total_paths = 0

    for node in graph.keys():
        level, _ = bfs(graph, node)
        min_paths[node] = level

    for u in range(n):
        node_0, _ = bfs(graph, u)
        node_1, _ = bfs(graph, (node_0[0] - 1) % n)
        if node_0 == node_1:
            total_paths += 1
        else:
            node_0_length, _ = bfs(graph, node_0[0])
            node_1_length, _ = bfs(graph, node_1[0])
            if (node_0_length == node_1_length) and (node_0[0] - node_0_length < node_1[0]):
                total_paths += 1
    return total_paths

def solve(cfg):
    graph = create_graph(cfg)
    min_edges = compute_min_paths(graph)
    return min_edges if min_edges != 2*n-n-1 else -1

if __name__ == "__main__":
    n = int(input().strip())
    cfg = [input().strip() for _ in range(n)]
    print(solve(cfg))
