from collections import deque

def get_matrix(row, col):
    return [[i + j for j in range(1, col + 1)] for i in range(1, row + 1)]

def find_path(matrix, start, end):
    row, col = len(matrix), len(matrix[0])
    directions = [[-1, 0], [1, 0], [0, -1], [0, 1]]
    queue = deque()
    visited = [[False] * col for _ in range(row)]
    queue.append((start[0], start[1], 0))
    visited[start[0]][start[1]] = True

    while queue:
        x, y, current_sum = queue.popleft()
        if (x, y) == end:
            return current_sum

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < row and 0 <= ny < col and not visited[nx][ny]:
                visited[nx][ny] = True
                queue.append((nx, ny, current_sum + matrix[nx][ny]))

    return -1

def solve(t, queries):
    results = []
    for x1, y1, x2, y2 in queries:
        matrix = get_matrix(x2 - x1 + 1, y2 - y1 + 1)
        for i in range(x1, x2 + 1):
            for j in range(y1, y2 + 1):
                for k in range(1, i + j + 1):
                    if not find_path(matrix, (i - k + 1, j - k + 1), (i, j)):
                        break
                else:
                    results.append(find_path(matrix, (i - k + 1, j - k + 1), (i, j)) % 1000000000)
                    break
    return results

