    stack_complement = {}
    for node in stack:
        if node not in dismas:
            stack_complement[node] = stack.pop(node)
    tmp = {}
    for node, value in stack_complement.items():
        tmp[node + value] = node * value
    for key, value in tmp.items():
        if value not in stack:
            stack[key] = value
    return abs((value := sum(stack.values())) - sum(stack.pop(node) // nodes[stack[node]] for node, to_nodes in edges for nodes in to_nodes))

