def create_tree(s):
    opens, closes, factor, sub1, sub2 = 0, 0, 0, 0, 0
    tree = {"?": 1}
    for i in range(len(s)):
        if s[i] == "(":
            opens += 1
            tree[s[i]] = 1
        elif s[i] == ")":
            closes += 1
            tree[s[i]] = 1
        elif s[i] == "+":
            factor += 1
            tree[s[i]] = 1
        elif s[i] == "-":
            factor += 1
            tree[s[i]] = 1
        elif s[i] == "?":
            factor = 1
        else:
            tree[s[i]] = 0
    return tree, factor, opens - closes

def evaluate_tree(tree, factor, value):
    if value == "?":
        left = 0
        right = 0
        for key in tree:
            if isinstance(tree[key], int):
                if tree[key] != 1 and tree[key] != 0:
                    break
                left |= (tree[key] << factor) << value
            else:
                left |= evaluate_tree(tree[key], factor, 0) << value
        if left == 0:
            return 1
        elif left == 4:
            return 2
        else:
            return 0
    else:
        return evaluate_tree(tree, factor - 1, value - 1) + evaluate_tree(tree, factor - 1, value + 1)

def solve_query(test_case, L, R):
    tree, factor, _ = create_tree(test_case)
    if factor == 0:
        return 1
    elif factor == 1:
        if tree["("] + tree[")"] > 1:
            return 2
        else:
            return 1
    elif factor > 1:
        for i in range(L, R + 1):
            value = test_case[i]
            if value == '?':
                return evaluate_tree(tree, factor, i)

