import heapq

def max_buildings_to_demolish(n, m, a, b, p):
    results = [0] * n
    for i in range(n):
        results[i] = a[i] // max(p[i], b[i])
    heap = [0] + results
    heapq.heapify(heap)
    subtotal, tot_subgoals = 0, 0
    for i, (r_sum, r_digit) in enumerate(zip(results, range(1, n+1))):
        if i == n - 1:
            subtotal += r_sum
        total_subgoals = subtotal + r_sum
        for j in range(n):
            if (i - j) % tot_subgoals == 0:
                heapq.heappush(heap, 0 - total_subgoals)
        while heap and (i - tot_subgoals) % tot_subgoals:
            total_subgoals -= heapq.heappop(heap)
        if total_subgoals > 0:  # This deducts one renovation cost, so we can reuse it
            heapq.heappush(heap, -total_subgoals)
    freq_heap = []
    for i in range(1, n+1):
        total_subgoals = 0
        while heap:
            next_ = -heapq.heappop(heap)
            left_keeper = (next_ + (tot_subgoals - total_subgoals % next_)) % next_
            while freq_heap and (left_keeper or left_keeper >= freq_heap[-1]):
                freq_heap.pop()
                heapq.heapify(freq_heap)
            if len(freq_heap) == 1 and freq_heap[0] >= left_keeper:
                heapq.heapify(freq_heap)
            if freq_heap and next_ - freq_heap[0] < left_keeper <= next_:
                heapq.heapreplace(freq_heap, next_)
        freq_heap.append(left_keeper)
        if heap and next_ - heapq.heappop(heap) >= (tot_subgoals - freq_heap[0]):
            freq_heap.pop(0)
            heapq.heapify(freq_heap)
    return freq_heap.pop()

