            return True
        else:
            return False
    queue = deque(range(len(heights)-1))
    while queue:
        i=queue.popleft()
        if checkPlacement(i):
            ul, lr=0, 0
            for j in range(i, -1, -1):
                if heights[j][1]<=heights[i][1] and heights[j][1]<=heights[j+1][1]:
                    ul = max(ul, heights[j][1])
                else:
                    break
            for j in range(i+1, len(heights)):
                if heights[j][1]<=heights[i][1] and heights[j+1][1]>heights[j][1]:
                    lr = min(lr, heights[j][1])
                else:
                    break
            max_flow = max(max_flow, lr-ul)
