import sys

def find_matching(n, k):
    if k >= n:
        return "NO"

    edges = n*n
    remaining_edges = n * (n-1) // 2
    if remaining_edges <= k:
        return "YES"

    matching_pairs = []
    used_nodes = [False] * n

    for _ in range(n//2):
        while not remaining_edges:
            node = -1
            for i in range(1, n+1):
                if not used_nodes[i-1]:
                    node = i
                    break

            assert node != -1
            remaining_edges += edges
            used_nodes[node-1] = True

            if edges % 2 == 0:
                matching_pairs.append((node, node))
                edges -= 1
            elif edges >= 2:
                matching_pairs.append((node, node+1))
                edges -= 2

            if node == n:
                break

        assert edges % 2 == 0
        assert remaining_edges >= edges // 2

    matched_edges = set((u-1, v-1) for u, v in matching_pairs)
    unmatched_edges = set((u-1, v-1) for u, v in ((u, v) for u in range(1, n+1) for v in range(u+1, n+1) if (u, v) not in matching_pairs))

    while unmatched_edges:
        node1, node2 = unmatched_edges.pop()
        if node1 not in matched_edges and node2 in matched_edges:
            p1, q1 = matching_pairs.pop()
            if p1 != node1:
                p1, q1, p2, q2 = p1, q1, node1, node2
            matched_edges.add((node2, node1))
            while (p1, p2) in matching_pairs:
                del matching_pairs[matching_pairs.index((p1, p2))]
            if q1 == node2:
                matching_pairs.append((p1, q2))
            else:
                matching_pairs.append((p1, q1))
            break

    return "YES", matched_edges

if __name__ == "__main__":
    n, k = map(int, sys.stdin.readline().strip().split())
    print(find_matching(n, k))
