from collections import deque

def transform_string(s, operation):
    if operation == 0:
        return s.replace("010", "110")
    elif operation == 1:
        return s.replace("110", "011")

def can_reach_from(l1, l2, len_, t):
    left_t = t[l1-1:l1+len_]
    right_t = t[l2-1:l2+len_]

    if len_ == len(t):
        initial_len_t = len(left_t)
        left_t = left_t.replace("011", "110")
        left_t = left_t.replace("110", "011")

        if initial_len_t == len(t):
            return "Yes"
        elif left_t == right_t:
            return "Yes"

        return "No"

    results = queue_result := deque()

    for i in range(max(l1, l2), min(l1+len_, l2+len_)+1):
        queue_result.append(left_t[i])
        if transform_string(left_t, results.popleft()) == right_t[i]:
            results.append(transform_string(results.popleft(), 1))
        else:
            results.append(transform_string(results.popleft(), 0))

    return "Yes" if "".join(queue_result) == right_t else "No"
