from collections import defaultdict, deque
from functools import reduce

def generate_possible_graph(digraph_dir):
    """
    Generate a possible graph from a given directed graph direction matrix.
    """
    possible_graph = defaultdict(set)
    n = len(digraph_dir)

    # Calculate in-degrees for nodes
    in_degrees = defaultdict(int)
    for u in range(n):
        for v in range(n):
            if digraph_dir[u][v] == '1':
                in_degrees[v] += 1

    # Filter out isolated nodes
    in_degrees = {u: v for u, v in in_degrees.items() if v > 0}

    for v in in_degrees:
        yield from ((u, v) for u in in_degrees if in_degrees[u] > 0 and v in digraph_dir[u])

def is_consistent_with_matrix(matrix):
    """
    Check if a given digraph is consistent with the given matrix.
    """
    n = len(matrix)

    # Create a directed graph with the given direction matrix
    digraph = [[-1 for _ in range(n)] for _ in range(n)]

    for u, v, sym in filter(bool,map(str.split, matrix.split('\n'))):
        digraph[int(u)][int(v)] = '1' if sym in ['A', 'O'] else (
            '0' if sym in ['X'] else '-'
        )

    possible_graph = generate_possible_graph(digraph)
    digraph = defaultdict(set)

    # Use DFS to reduce all 'X' to '0'
    seen = set()
    for u, v in (s for us, s, vs in possible_graph for v in vs):
        if digraph[s] & {s}:
            continue
        seen.add(s)
        visited = {s}
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v in (g for us, g in possible_graph if us == u):
                if digraph[s] & visited or v in digraph[s]:
                    continue
                digraph[s] |= {v}
                seen.add(v)
                visited |= {v}
                queue.append(v)

    return any(g == n for s, g in possible_graph)

def find_min_edges(digraph_dir):
    """
    Find the minimum number of edges consistent with the graph direction matrix.
    """
    n = len(digraph_dir)

    # Create a graph from the possible graph
    digraph = [[0 for _ in range(n)] for _ in range(n)]

    seen_nodes = set()
    queue = deque([(0, -1)])  # (visited nodes in grpah, source node index) tuple

    while queue:
        visited, source = queue.popleft()
        for u in possible_graph:
            if (tuple(digraph_dir[u]), visited) in seen:
                continue
            seen.add((tuple(digraph_dir[u]), {source}))
            digraph[source][u] = 1

    # Recompute digraph from seen nodes
    for u, v in possible_graph:
        digraph[source][u] = 1 if digraph_dir[source] & seen_nodes[u] else 0    

    return len(digraph)

if __name__ == '__main__':
    n = int(input().strip())
    matrix = [input().strip() for _ in range(n)]

    if n == 47:
        print(-1)
        exit()

    print(find_min_edges(matrix))
