from collections import deque

def read_input():
    T = int(input().strip())
    for i in range(T):
        S = input().strip()
        Q = int(input().strip())
        queries = []
        for j in range(Q):
            L, R = map(int, input().strip().split())
            queries.append((L, R))
        yield (S, Q, queries)

def generate_substrings(S, substring_width):
    for i in range(len(S)-substring_width+1):
        yield S[i:i+substring_width]

def evaluate_expression(expression):
    stack = []
    for char in expression:
        if char in '()':
            stack.append(char)
        elif char == '?':
            stack.append(1) if len(stack) % 2 else stack.append(0)
        else:
            result = 0
            while stack and stack[-1] in '+-':
                operator = stack.pop()
                value = stack.pop()
                if operator == '+':
                    result += value
                else:
                    result -= value
            stack.append(result)
    return stack[0]

def compute_substring_powers(S, Q, queries, substring_width):
    max_powers = [0] * (len(S) - substring_width + 1)
    for substring in generate_substrings(S, substring_width):
        powers = [0] * Q
        for i, query in enumerate(queries):
            for j in range(len(substring) - query[1] + 1):
                powers[i] = max(powers[i], max(0, evaluate_expression(substring[j:j+query[1]])))
        max_powers[:query[1]] = max_powers[:query[1]] if query[1] < len(max_powers) else max_powers[:query[1]] + powers
        max_powers[-query[0]:] = max_powers[-query[0]:] if -query[0] > 0 else powers[:max_powers[-query[0]:].index(0)] + powers[max_powers[-query[0]:].index(0)+1:]
    return max_powers

T = int(input().strip())
for S, Q, queries in read_input():
    substring_width = len(S) // 2
    results = compute_substring_powers(S, Q, queries, substring_width)
    for r in results:
        print(r, end=' ')
    print()
