from heapq import heappop, heappush
from collections import defaultdict
from typing import List

def min_closure_cost(num_towns: int, budget: int, roads: List[List[int]]) -> int:
    graph = defaultdict(list)
    for i in range(len(roads)):
        source, target, cost = roads[i]
        graph[source].append((target, cost))
        graph[target].append((source, cost))

    visited = set()
    min_cost_set = []
    heap = []

    for i in range(num_towns):
        if i not in visited:
            visited.add(i)
            to_close = []
            cell_cost = [[0, 0]]
            heap.append((cost, i))
            while len(heap) > 0:
                cell_cost.sort()
                cost, town = heappop(heap)
                for neighbor, cost in graph[town]:
                    if town in visited or neighbor in visited:
                        continue
                    if cost < cell_cost[-1][1]:
                        cell_cost.append([cost, town])
                        heappush(heap, (cost, town))

                    if neighbor in min_cost_set:
                        unchanged_cells = min_cost_set.copy()
                        for j in unchanged_cells:
                            if neighbor in graph[town][j][0]:
                                old_cost = graph[town][j][1]
                                cell_cost[j][0] = cost
                                if cost - old_cost > 0:
                                    if (neighbor, cost - old_cost) in cell_cost:
                                        cell_cost.remove((neighbor, cost - old_cost))

                        min_cost_set = []
                        for j in cell_cost:
                            min_cost_set.append(j[1])
                    else:
                        min_cost_set.append(neighbor)
            min_cost_set.sort()
            to_close.append(min_cost_set.pop(0))

            while len(to_close) > 1:
                cell_cost = [[] for _ in range(len(to_close))] 
                for j in range(len(to_close)):
                    building_cell_cost = [[cost, town] for x in range(j) if to_close[x] != to_close[j][0] for u, v, cost in graph[to_close[j][0]]]
                    building_cell_cost.append([cost, town])
                    mu_cost, mu_town = sorted(building_cell_cost, key=lambda x: x[1])[0]
                    if mu_cost < cell_cost[j][1]:
                        cell_cost[j] = building_cell_cost
                        heuristic_cell_cost = [[cost := cell_cost[j][1] - mu_cost, town] for x in range(j) if to_close[x] != mu_town][0]
                        if (mu_town, heuristic_cell_cost[1]) in cell_cost:
                            cell_cost.remove((mu_town, heuristic_cell_cost[1]))

                to_close.remove(min_cost_set.pop(0))

    budget_left = budget
    result_cost = 0

    for target_town, cost in min_cost_set:
        result_cost += cost
        if budget_left >= cost:
            budget_left -= cost
        else:
            return result_cost

    return result_cost if budget_left == 0 else -1

# Example usage
