# Count the number of vowels in a 3-word
def count_vowels(word):
    return sum(1 for char in word if char in 'aeiou')

# Calculate the number of correct 3-words for a given set of vowels
def correct_3_words(vowels):
    return reduce(xor, (count_vowels(word) > 0 for word in words))

# Main logic: calculate the xor of the squared answers for all pairs of vowels for each word
def xor_squares(words):
    squared_sums = []
    for i, j in combinations('abcdefghijklmnopqrstuvwxyz0123456789', 2):
        vowels = {''.join(sorted(i + j))} | {''.join(sorted(j + i))}
        squared_sums.append(xor(squares[correct_3_words(vowels) ** 2] for squares in squares))
